ArrayList<Particle> pts;
let onPressed, showInstruction = true;
let f;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  smooth();
  colorMode(HSB);
  rectMode(CENTER);

  pts = new ArrayList<Particle>();

  f = createFont("Calibri", 24, true);

  background(0);
}

function draw() {
  if (showInstruction) drawInstruction();

  if (onPressed) {
    for (i=0;i<10;i++) {
      let newP = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), i+pts.size(), i+pts.size());
      pts.add(newP);
    }
  }

  for (i=pts.size()-1; i>-1; i--) {
    let p = pts.get(i);
    if (p.dead) {
      pts.remove(i);
    }else{
      p.update();
   	  p.display();
    }
  }
}

function drawInstruction(){
  background(255);
  fill(128);
  textAlign(CENTER, CENTER);
  textFont(f);
  textLeading(36);
  text("Drag and draw." + "\n" +
       "Press 'c' to clear the stage." + "\n"
       ,width*0.5, height*0.5);
}

// === Tab: Particle ===
class Particle{
  loc, vel, acc;
  lifeSpan, passedLife;
  dead;
  alpha, weight, weightRange, decay, xOfst, yOfst;
  c;

  constructor(x, y, xOfst, yOfst){
    loc = new PVector(x, y);

    let randDegrees = random(3600);
    vel = new PVector(cos(radians(randDegrees)), sin(radians(randDegrees)));
    vel.mult(random(5));

    acc = new PVector(0,0);
    lifeSpan = int(random(300, 900));
    decay = random(0.5, 1);
    c = color(random(255),random(255),random(255));
    weightRange = random(10,30);

    this.xOfst = xOfst;
    this.yOfst = yOfst;
  }

  function update(){
    if(passedLife>=lifeSpan){
      dead = true;
    }else{
      passedLife++;
    }

    alpha = float(lifeSpan-passedLife)/lifeSpan * 70+50;
    weight = float(lifeSpan-passedLife)/lifeSpan * weightRange;

    acc.set(0,0);

    let rn = (noise((loc.x+frameCount+xOfst)*.01, (loc.y+frameCount+yOfst)*.01)-.5)*TWO_PI*4;
    let mag = noise((loc.y-frameCount)*.01, (loc.x-frameCount)*.01);
    let dir = new PVector(cos(rn),sin(rn));
    acc.add(dir);
    acc.mult(mag);

    let randRn = random(TWO_PI);
    let randV = new PVector(cos(randRn), sin(randRn));
    randV.mult(.25);
    acc.add(randV);

    vel.add(acc);
    vel.mult(decay);
    vel.limit(3);
    loc.add(vel);
  }

  function display(){
    strokeWeight(weight+1.5);
    stroke(10, alpha);
    point(loc.x, loc.y);

    strokeWeight(weight);
    stroke(c);
    point(loc.x, loc.y);
  }
}

// === Tab: io ===
function mousePressed() {
  onPressed = true;
  if (showInstruction) {
    background(255);
    showInstruction = false;
  }
}

function mouseReleased() {
  onPressed = false;
}

function keyPressed() {
  if (key == 'c') {
    for (i=pts.size()-1; i>-1; i--) {
      var p = pts.get(i);
      pts.remove(i);
    }
    background(0);
  }
}

